from solution import intersection
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def ref_is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True


def ref_intersection(a, b) -> str:
    l = max(a[0], b[0])
    r = min(a[1], b[1])
    if l > r:
        return "NO"
    length = r - l
    return "YES" if ref_is_prime(length) else "NO"


# --- concrete samples from spec ---

def test_sample_single_point_length_zero_is_not_prime():
    assert intersection((1, 2), (2, 3)) == "NO"


def test_sample_length_one_is_not_prime():
    assert intersection((-1, 1), (0, 4)) == "NO"


def test_sample_length_two_is_prime():
    assert intersection((-3, -1), (-5, 5)) == "YES"


def test_spec_example_length_one_is_not_prime():
    assert intersection((1, 3), (2, 4)) == "NO"


# --- explicit prime / composite boundaries ---

def test_prime_length_2_returns_YES():
    # intersection (0,2) length 2 prime
    assert intersection((0, 2), (0, 2)) == "YES"


def test_prime_length_3_returns_YES():
    assert intersection((0, 3), (0, 3)) == "YES"


def test_prime_length_5_returns_YES():
    assert intersection((0, 5), (0, 5)) == "YES"


def test_prime_length_7_returns_YES():
    assert intersection((0, 7), (0, 7)) == "YES"


def test_composite_even_length_4_returns_NO():
    # 4 is not prime; catches divisor-2 bug
    assert intersection((0, 4), (0, 4)) == "NO"


def test_composite_even_length_6_returns_NO():
    assert intersection((0, 6), (0, 6)) == "NO"


def test_composite_even_length_8_returns_NO():
    assert intersection((0, 8), (0, 8)) == "NO"


def test_composite_even_length_10_returns_NO():
    assert intersection((0, 10), (0, 10)) == "NO"


def test_composite_even_length_12_returns_NO():
    assert intersection((0, 12), (0, 12)) == "NO"


def test_composite_odd_length_9_returns_NO():
    assert intersection((0, 9), (0, 9)) == "NO"


def test_composite_length_0_returns_NO():
    assert intersection((2, 2), (2, 2)) == "NO"


def test_composite_length_1_returns_NO():
    assert intersection((0, 1), (0, 1)) == "NO"


def test_disjoint_intervals_return_NO():
    assert intersection((1, 2), (5, 6)) == "NO"
    assert intersection((5, 6), (1, 2)) == "NO"
    assert intersection((-10, -5), (5, 10)) == "NO"


def test_touching_but_disjoint_returns_NO():
    # (1,2) and (3,4) do not intersect
    assert intersection((1, 2), (3, 4)) == "NO"


def test_containment_preserves_length():
    # (1,10) intersect (3,7) = (3,7) length 4 -> not prime
    assert intersection((1, 10), (3, 7)) == "NO"
    # (1,10) intersect (3,6) = (3,6) length 3 -> prime
    assert intersection((1, 10), (3, 6)) == "YES"


# --- properties ---

def test_property_output_domain_is_YES_or_NO():
    for a, b in [((0, 2), (0, 2)), ((0, 4), (0, 4)), ((1, 2), (5, 6))]:
        assert intersection(a, b) in ("YES", "NO")


@given(n=st.integers(min_value=0, max_value=30))
def test_property_identical_intervals_match_primality_of_length(n):
    # (0,n) intersect (0,n) = (0,n), length n
    expected = "YES" if ref_is_prime(n) else "NO"
    assert intersection((0, n), (0, n)) == expected


@given(n=st.integers(min_value=0, max_value=30))
def test_property_shifted_identical_intervals_match_primality(n):
    # (-5, -5+n) intersect itself has length n, tests negatives
    expected = "YES" if ref_is_prime(n) else "NO"
    assert intersection((-5, -5 + n), (-5, -5 + n)) == expected


@given(
    s1=st.integers(min_value=-10, max_value=10),
    len1=st.integers(min_value=0, max_value=10),
    s2=st.integers(min_value=-10, max_value=10),
    len2=st.integers(min_value=0, max_value=10),
)
def test_property_matches_reference_model(s1, len1, s2, len2):
    a = (s1, s1 + len1)
    b = (s2, s2 + len2)
    assert intersection(a, b) == ref_intersection(a, b)


@given(
    s1=st.integers(min_value=-10, max_value=10),
    len1=st.integers(min_value=0, max_value=10),
    s2=st.integers(min_value=-10, max_value=10),
    len2=st.integers(min_value=0, max_value=10),
)
def test_property_commutativity(s1, len1, s2, len2):
    a = (s1, s1 + len1)
    b = (s2, s2 + len2)
    assert intersection(a, b) == intersection(b, a)


@given(
    s1=st.integers(min_value=-10, max_value=10),
    len1=st.integers(min_value=0, max_value=10),
    gap=st.integers(min_value=1, max_value=10),
    len2=st.integers(min_value=0, max_value=10),
)
def test_property_disjoint_always_NO(s1, len1, gap, len2):
    # b starts strictly after a ends => no intersection
    a = (s1, s1 + len1)
    b = (s1 + len1 + gap, s1 + len1 + gap + len2)
    assert intersection(a, b) == "NO"
    assert intersection(b, a) == "NO"


@given(length=st.integers(min_value=0, max_value=20))
def test_property_partial_overlap_length(length):
    # (0, 10) intersect (10 - length, 20) = (10-length, 10), length = `length`
    # if length == 0 then single point (10,10), length 0
    a = (0, 10)
    b = (10 - length, 20)
    expected = "YES" if ref_is_prime(length) else "NO"
    assert intersection(a, b) == expected
    assert intersection(b, a) == expected
